    let w10 = (f.x)       * (1.0 - f.y);
    let w01 = (1.0 - f.x) * (f.y);
    let w11 = (f.x)       * (f.y);

    let v00 = select(0.0, 1.0, p00.w != 0.0);
    let v10 = select(0.0, 1.0, p10.w != 0.0);
    let v01 = select(0.0, 1.0, p01.w != 0.0);
